const data={object:null,work:null,area:null,start:null,budget:null,client:null,id:null};const chat=document.querySelector('#chat'),actions=document.querySelector('#actions');const pause=()=>new Promise(r=>setTimeout(r,180));
const steps={objects:[['Квартира','жилое помещение'],['Дом','частный объект'],['Офис','коммерческое помещение']],works:[['Косметический ремонт','обновление отделки'],['Капитальный ремонт','полный комплекс работ'],['Отдельные работы','одна или несколько задач']],starts:[['В течение месяца'],['Через 1–2 месяца'],['Пока уточняю сроки']],budgets:[['До 300 000 ₽'],['300 000–700 000 ₽'],['Более 700 000 ₽'],['Нужна оценка']]};
function msg(text,type='bot',ok=false){const x=document.createElement('div');x.className=`msg ${type}${ok?' success':''}`;x.textContent=text;chat.append(x);chat.scrollTop=chat.scrollHeight}function options(items,fn){actions.innerHTML='';items.forEach(([name,meta=''])=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`${name}<small>${meta}</small>`;b.onclick=()=>fn(name);actions.append(b)})}async function bot(t){await pause();msg(t)}
function draw(){const rows=[['Объект',data.object],['Работы',data.work],['Площадь',data.area&&`${data.area} м²`],['Старт',data.start],['Бюджет',data.budget],['Клиент',data.client?.name]];document.querySelector('#fields').innerHTML=rows.map(([k,v])=>`<div class="field"><span>${k}</span><b>${v||'—'}</b></div>`).join('')}
async function start(){Object.keys(data).forEach(k=>data[k]=null);chat.innerHTML='';actions.innerHTML='';document.querySelector('#status').textContent='Черновик';document.querySelector('#status').className='';document.querySelector('#notice').textContent='Заполненные данные появятся здесь.';draw();msg('Здравствуйте! Соберу исходные данные для расчёта ремонта. Какой у вас объект?');options(steps.objects,x=>pick('object',x,'Какие работы планируются?',steps.works,work))}
async function pick(key,value,question,next,fn){data[key]=value;msg(value,'user');draw();actions.innerHTML='';await bot(question);options(next,fn)}function work(x){pick('work',x,'Укажите примерную площадь объекта.',[['Ввести площадь']],()=>areaForm())}
function areaForm(){actions.innerHTML=`<form class="form" id="area"><input name="area" type="number" min="5" max="9999" placeholder="Например, 62" aria-label="Площадь" required><button>Продолжить</button></form>`;document.querySelector('#area').onsubmit=async e=>{e.preventDefault();data.area=e.currentTarget.area.value;msg(`${data.area} м²`,'user');draw();actions.innerHTML='';await bot('Когда планируете начать работы?');options(steps.starts,x=>pick('start',x,'Какой бюджет рассматриваете?',steps.budgets,budget))}}
function budget(x){data.budget=x;msg(x,'user');draw();contact() }async function contact(){actions.innerHTML='';await bot('Оставьте имя и телефон. При желании фотографии можно отправить менеджеру после создания заявки.');actions.innerHTML=`<form class="form" id="contact"><input name="name" placeholder="Имя" aria-label="Имя" required><input name="phone" type="tel" placeholder="+7 999 000-00-00" aria-label="Телефон" required><small id="err"></small><button>Сформировать заявку</button></form>`;document.querySelector('#contact').onsubmit=submit}
async function submit(e){e.preventDefault();const name=e.currentTarget.name.value.trim(),phone=e.currentTarget.phone.value.trim();if(!name||phone.replace(/\D/g,'').length<11){document.querySelector('#err').textContent='Проверьте имя и телефон.';return}data.client={name,phone};msg(`${name}, ${phone}`,'user');draw();actions.innerHTML='';await bot(`Проверьте данные:\n${data.object} · ${data.area} м²\n${data.work}\nСтарт: ${data.start}\nБюджет: ${data.budget}\n${name}, ${phone}`);options([['Отправить заявку','данные верны'],['Начать заново','изменить ответы']],x=>x.startsWith('Отправить')?confirm():start())}
async function confirm(){msg('Отправить заявку','user');actions.innerHTML='';data.id='FX-'+String(Date.now()).slice(-6);await bot(`Заявка ${data.id} принята ✅\nМенеджер получил сводку и сможет связаться с вами.`,true);document.querySelector('#status').textContent='Принята';document.querySelector('#status').className='done';document.querySelector('#notice').textContent=`${data.id}: ${data.client.name}, ${data.object}, ${data.area} м², ${data.work}. ${data.client.phone}`;options([['Проверить статус','текущий статус заявки'],['Отменить заявку','освободить обращение']],x=>x.startsWith('Проверить')?showStatus():cancel())}
async function showStatus(){msg('Проверить статус','user');actions.innerHTML='';await bot(`${data.id}\nСтатус: заявка передана менеджеру.`);options([['Вернуться']],confirmActions)}function confirmActions(){options([['Проверить статус'],['Отменить заявку']],x=>x.startsWith('Проверить')?showStatus():cancel())}async function cancel(){msg('Отменить заявку','user');actions.innerHTML='';await bot(`${data.id} отменена. Данные больше не участвуют в обработке.`);document.querySelector('#status').textContent='Отменена';document.querySelector('#status').className='';options([['Создать новую заявку']],start)}
document.querySelectorAll('[data-reset]').forEach(x=>x.onclick=start);start();
